return {["scripts/actions/spells/trust/flaviria_uc.lua"]={["Path"]="scripts/actions/spells/trust/flaviria_uc.lua",["SHA256"]="df1f50492f7f678890bd0a7fa4cb5abbf9d56055c148d9ce5443d7892a20851e",["Text"]="-----------------------------------\n-- Trust: Flaviria UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/gadalar.lua"]={["Path"]="scripts/actions/spells/trust/gadalar.lua",["SHA256"]="2dbdbbc458b1b54f2eed64288235fe68c78d7c86b903086a59cc79daa0156e4e",["Text"]="-----------------------------------\n-- Trust: Gadalar\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/gessho.lua"]={["Path"]="scripts/actions/spells/trust/gessho.lua",["SHA256"]="84e0c4b9a8a41248f407495f361abaad554111cc33fbdf59234536e478ca7c66",["Text"]="-----------------------------------\n-- Trust: Gessho\n-- Will only use the highest tier debuff available, but will use both Utsusemi spells.\n-- Will maintain Yonin full time.\n-- Holds TP until 1500 to try to close skillchains.\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.NAJA_SALAHEEM] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.ABQUHBAH] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    mob:addMobMod(xi.mobMod.CAN_PARRY, 1)\n\n    mob:addMod(xi.mod.MAIN_DMG_RATING, xi.trust.modGrowthValMax(mob, 35))\n    mob:addMod(xi.mod.DOUBLE_ATTACK, xi.trust.modGrowthValMax(mob, 15))\n    mob:addMod(xi.mod.ACC, xi.trust.modGrowthValMax(mob, 200))\n    mob:addMod(xi.mod.EVA, xi.trust.modGrowthValMax(mob, 125))\n    mob:addMod(xi.mod.FASTCAST, 30)\n    mob:addMod(xi.mod.ENMITY, 10)\n\n    local lvl = mob:getMainLvl()\n\n    if lvl >= 5 then\n        mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\n    end\n\n    if lvl >= 40 then\n        mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.YONIN }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.YONIN })\n    end\n\n    mob:addGambit(ai.t.SELF,   { ai.c.NOT_STATUS, xi.effect.COPY_IMAGE }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.UTSUSEMI })\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.BLINDNESS  }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.KURAYAMI }, 30)\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.SLOW       }, { ai.r.MA, ai.s.HIGHEST,  xi.magic.spellFamily.HOJO     }, 30)\n\n    mob:addListener('WEAPONSKILL_USE', 'GESSHO_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == xi.mobSkill.SHIBARAKU_TRUST then -- Shibaraku\n            -- You have left me no choice. Prepare yourself!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.RANDOM, 1500)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/gilgamesh.lua"]={["Path"]="scripts/actions/spells/trust/gilgamesh.lua",["SHA256"]="04142797e9b8d930ad2931f510c222e151e665072bcc80cc08d3fb310d5f675c",["Text"]="-----------------------------------\n-- Trust: Gilgamesh\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/halver.lua"]={["Path"]="scripts/actions/spells/trust/halver.lua",["SHA256"]="e50e95baa355e1ff034f066cae1e34e2abc8a457d969bb8207603ac91fc494d6",["Text"]="-----------------------------------\n-- Trust: Halver\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/i_shield_uc.lua"]={["Path"]="scripts/actions/spells/trust/i_shield_uc.lua",["SHA256"]="475b08e394c3d98823211a1f1861aca5695e04396c8261cba8fc24d26ae52f7f",["Text"]="-----------------------------------\n-- Trust: Invincible Shield UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ingrid.lua"]={["Path"]="scripts/actions/spells/trust/ingrid.lua",["SHA256"]="cb10baba4df79de98aa6ceb28c78ecc1375c5a1ff2739b51a3dde9e2865e3600",["Text"]="-----------------------------------\n-- Trust: Ingrid\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.INGRID_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/ingrid_ii.lua"]={["Path"]="scripts/actions/spells/trust/ingrid_ii.lua",["SHA256"]="e6c46ef8066804038e1662e16b0b241972a78302d5c475e1f6354be1774af8a0",["Text"]="-----------------------------------\n-- Trust: Ingrid II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.INGRID)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/iroha.lua"]={["Path"]="scripts/actions/spells/trust/iroha.lua",["SHA256"]="3fd2a27c47701f043b80b2ab4ef76c427beca65ddea89af7b36c6d6a88b12194",["Text"]="-----------------------------------\n-- Trust: Iroha\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.IROHA_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/iroha_ii.lua"]={["Path"]="scripts/actions/spells/trust/iroha_ii.lua",["SHA256"]="04ec1a636c775e4ba94fec6c87885aaaf5004907698768e4dc6b7d9c93af4f2d",["Text"]="-----------------------------------\n-- Trust: Iroha II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.IROHA)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/iron_eater.lua"]={["Path"]="scripts/actions/spells/trust/iron_eater.lua",["SHA256"]="5578f404741f8ff053704ff78a8e6cd4fa43020f04b4dc2f5801917e00e91d08",["Text"]="-----------------------------------\n-- Trust: Iron Eater\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.NAJI] = xi.trust.messageOffset.TEAMWORK_1,\n    })\n\n    mob:addGambit(ai.t.MASTER, { ai.c.HPP_LT, 50 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.PROVOKE })\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/jakoh_uc.lua"]={["Path"]="scripts/actions/spells/trust/jakoh_uc.lua",["SHA256"]="12dad3387ccac08141315eb54bea8fa4f1fc754e4f0b3cb1e840b0c2e3c408c5",["Text"]="-----------------------------------\n-- Trust: Jakoh Wahcondalo UC\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/joachim.lua"]={["Path"]="scripts/actions/spells/trust/joachim.lua",["SHA256"]="2f7a06ffe8bf982d40078ad63e2c923252224cfd48bb4cd5ee1dbdccf745e872",["Text"]="-----------------------------------\n-- Trust: Joachim\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    -- Records of Eminence: Alter Ego: Joachim\n    if caster:getEminenceProgress(937) then\n        xi.roe.onRecordTrigger(caster, 937)\n    end\n\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.POISON }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.POISONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.CURSE_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n\n    -- TODO: BRD trusts need better logic and major overhaul, for now they compliment each other\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.MARCH }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.MARCH })\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.BALLAD }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.MAGES_BALLAD })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    -- Try and ranged attack every 60s\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.RATTACK, 0, 0 }, 60)\n\n    mob:setAutoAttackEnabled(false)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.MID_RANGE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/karaha-baruha.lua"]={["Path"]="scripts/actions/spells/trust/karaha-baruha.lua",["SHA256"]="419e824b40fde71861784ad505843e1ba7cd9118d153cead9ffcd68d39829011",["Text"]="-----------------------------------\n-- Trust: Karaha-Baruha\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    -- TODO: Add logic so that Spirit Taker is used if lower on mana, instead of holding to close TP.\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.STAR_SIBYL] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.ROBEL_AKBEL] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 55 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECTRA })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELLRA })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECT })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELL })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.HASTE })\n    -- -na Spells\n    mob:addGambit(ai.t.PARTY, { ai.l.OR(\n                                { ai.c.STATUS, xi.effect.CURSE_I },\n                                { ai.c.STATUS, xi.effect.CURSE_II },\n                                { ai.c.STATUS, xi.effect.BANE },\n                                { ai.c.STATUS, xi.effect.DOOM })\n                                }, { ai.r.MS, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n\n    -- Handle his Barelementra tracking --\n    mob:addListener('TAKE_DAMAGE', 'KARAHA-BARUHA_TAKE_DAMAGE', function(mobArg, amount, attacker, attackType, damageType)\n        local elemTable = {\n            [xi.damageType.FIRE] = { effect = xi.effect.BARFIRE, spell = 66 },\n            [xi.damageType.ICE] = { effect = xi.effect.BARBLIZZARD, spell = 67 },\n            [xi.damageType.WIND] = { effect = xi.effect.BARAERO, spell = 68 },\n            [xi.damageType.EARTH] = { effect = xi.effect.BARSTONE, spell = 69 },\n            [xi.damageType.THUNDER] = { effect = xi.effect.BARTHUNDER, spell = 70 },\n            [xi.damageType.WATER] = { effect = xi.effect.BARWATER, spell = 71 },\n        }\n        local elemData = elemTable[damageType]\n        if elemData and not mobArg:getStatusEffect(elemData.effect) then\n            mobArg:timer(30, function(mobBar)\n                mobBar:castSpell(elemData.spell)\n            end)\n        end\n    end)\n\n    mob:addListener('WEAPONSKILL_USE', 'KARAHA-BARUHA_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3336 then -- Howling Moon\n        -- The light shall never fade!\n            if math.randomInt(1, 100) <= 25 then\n                xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n            end\n        end\n    end)\n\n    if\n        mob:getMPP() < 30\n    then\n        mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\n    else\n        mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.HIGHEST, 3000)\n    end\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/kayeel-payeel.lua"]={["Path"]="scripts/actions/spells/trust/kayeel-payeel.lua",["SHA256"]="bb045bcb81e983b7b76d6ca3edf9a54b0164b4eef760a8a63ee4f715b3c70f8d",["Text"]="-----------------------------------\n-- Trust: Kayeel-Payeel\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/king_of_hearts.lua"]={["Path"]="scripts/actions/spells/trust/king_of_hearts.lua",["SHA256"]="0dff933fb2038616257eace95b6110e1207fa981f019942187e641bd5f0267de",["Text"]="-----------------------------------\n-- Trust: King of Hearts\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/klara.lua"]={["Path"]="scripts/actions/spells/trust/klara.lua",["SHA256"]="c19fec6f83edf729eedbfe36f309f74acca8d14be1f775d64ded634f4db9efce",["Text"]="-----------------------------------\n-- Trust: Klara\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/koru-moru.lua"]={["Path"]="scripts/actions/spells/trust/koru-moru.lua",["SHA256"]="3024f3a5db64c8dd737e1154cf370109ea247174ac9d8f44bb32ee40ee1dd2b5",["Text"]="-----------------------------------\n-- Trust: Koru-Moru\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.SHANTOTTO] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.SHANTOTTO_II] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.AJIDO_MARUJIDO] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    mob:addGambit(ai.t.SELF, { ai.c.MPP_LT, 5 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.CONVERT })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 50 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.MELEE, { ai.c.NOT_STATUS, xi.effect.HASTE }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.HASTE })\n\n    mob:addGambit(ai.t.CASTER, {\n        { ai.c.NOT_STATUS, xi.effect.REFRESH },\n        { ai.c.NOT_STATUS, xi.effect.SUBLIMATION_ACTIVATED },\n        { ai.c.NOT_STATUS, xi.effect.SUBLIMATION_COMPLETE },\n    }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.REFRESH })\n\n    mob:addGambit(ai.t.TANK, { ai.c.NOT_STATUS, xi.effect.REFRESH }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.REFRESH })\n\n    mob:addGambit(ai.t.RANGED, {\n            { ai.c.NOT_STATUS, xi.effect.FLURRY_II }, -- xi.effect.FLURRY_II is not a typo\n            { ai.c.NOT_STATUS, xi.effect.HASTE }, -- No overwriting Haste\n        }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.FLURRY })\n\n    mob:addGambit(ai.t.TOP_ENMITY, { ai.c.NOT_STATUS, xi.effect.PHALANX }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PHALANX_II })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.STATUS_FLAG, xi.effectFlag.DISPELABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.DISPEL })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.DIA }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.DIA }, 60)\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.SLOW }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SLOW }, 60)\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.EVASION_DOWN }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.DISTRACT }, 60)\n\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECT })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELL })\n\n    mob:setAutoAttackEnabled(false)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NO_MOVE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/kukki-chebukki.lua"]={["Path"]="scripts/actions/spells/trust/kukki-chebukki.lua",["SHA256"]="123b74e226ed0f474df2282c86b5fdd162caa0a24e0e6471a1eb24bf5017c0bb",["Text"]="-----------------------------------\n-- Trust: Kukki-Chebukki\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/kupipi.lua"]={["Path"]="scripts/actions/spells/trust/kupipi.lua",["SHA256"]="beb5bd3569662da1f5908ee6b85ecac4808ac7aa97a372b51acc25ea86f26160",["Text"]="-----------------------------------\n-- Trust: Kupipi\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    local windurstFirstTrust = caster:getCharVar('WindurstFirstTrust')\n    local zone = caster:getZoneID()\n\n    if\n        windurstFirstTrust == 1 and\n        (zone == xi.zone.EAST_SARUTABARUTA or zone == xi.zone.WEST_SARUTABARUTA)\n    then\n        caster:setCharVar('WindurstFirstTrust', 2)\n    end\n\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.SHANTOTTO] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.STAR_SIBYL] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 25 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SLEEP_II }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.HPP_LT, 75 }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.CURE })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.PROTECT }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PROTECTRA })\n    mob:addGambit(ai.t.PARTY, { ai.c.NOT_STATUS, xi.effect.SHELL }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SHELLRA })\n\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.POISON }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.POISONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.PARALYNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.BLINDNESS }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.BLINDNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.SILENCE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.SILENA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.PETRIFICATION }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.STONA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.DISEASE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.VIRUNA })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS, xi.effect.CURSE_I }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.CURSNA })\n\n    mob:addGambit(ai.t.SELF, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n    mob:addGambit(ai.t.PARTY, { ai.c.STATUS_FLAG, xi.effectFlag.ERASABLE }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.ERASE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.PARALYSIS }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.PARALYZE }, 60)\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.SLOW }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.SLOW }, 60)\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_STATUS, xi.effect.FLASH }, { ai.r.MA, ai.s.SPECIFIC, xi.magic.spell.FLASH }, 60)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NO_MOVE)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/kupofried.lua"]={["Path"]="scripts/actions/spells/trust/kupofried.lua",["SHA256"]="667d2faef12fc7ecacdc9538e9b24370f5bcd999b31f2880913c3b9f271cb81e",["Text"]="-----------------------------------\n-- Trust: Kupofried\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NON_COMBAT)\n\n    mob:addMod(xi.mod.AURA_SIZE, 600) -- Trust have a 12 yalm aura 6 base + 6 from mod\n\n    local effectParams =\n    {\n        power = 6,\n        origin = mob,\n        tick = 3,\n        subType = xi.effect.TRUST_AURA_EXP,\n        subPower = 20,\n        subIcon = xi.effect.DEDICATION,\n        tier = xi.auraTarget.ALLIES,\n        flag = xi.effectFlag.AURA\n    }\n\n    mob:addStatusEffect(xi.effect.COLURE_ACTIVE, effectParams)\n\n    mob:addGambit(ai.t.SELF, { { ai.c.TIMER, 5 }, { ai.c.RANDOM, 45 } }, { ai.r.ANIM_STRING, ai.s.RANDOM_ANIMATION, 4 })\n\n    mob:setAutoAttackEnabled(false)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/kuyin_hathdenna.lua"]={["Path"]="scripts/actions/spells/trust/kuyin_hathdenna.lua",["SHA256"]="d412c54961fb172950857f729fd3bd6358eb7e19e6c0db0e7381cc1d568926c5",["Text"]="-----------------------------------\n-- Trust: Kuyin Hathdenna\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    local master = mob:getMaster()\n    local hasTitle = false\n    local titleBonus = 0\n\n    if master then\n        hasTitle = master:hasTitle(xi.title.KIT_EMPATHIZER)\n    end\n\n    if hasTitle then\n        -- Kyuin only says this line when the master has the title \"Kit Empathizer\" from the mog garden quest to enable her employment.\n        xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n        titleBonus = 1\n    else\n        -- No title: I'd like you to gimme a job.\n        xi.trust.message(mob, xi.trust.messageOffset.TEAMWORK_1)\n    end\n\n    mob:setMobMod(xi.mobMod.TRUST_DISTANCE, xi.trust.movementType.NON_COMBAT)\n\n    mob:addMod(xi.mod.AURA_SIZE, 600) -- Trust have a 12 yalm aura 6 base + 6 from mod\n\n    local employmentBonus = 0 -- TODO: Add dex boost from mog garden employment (not implimented yet).\n    -- +1 Bonus when Kuyin is employed in your Mog Garden.\n    -- +1 Bonus when the player has the title \"Kit Empathizer\".\n\n    local effectParams =\n    {\n        power = 6,\n        origin = mob,\n        tick = 3,\n        subType = xi.effect.TRUST_AURA_ACC,\n        subPower = mob:getMainLvl() + employmentBonus + titleBonus, -- the effect script will adjust the power using xi.trust.trustAuraValue in trust.lua\n        subIcon = xi.effect.GEO_ACCURACY_BOOST,\n        tier = xi.auraTarget.ALLIES,\n        flag = xi.effectFlag.AURA\n    }\n\n    mob:addStatusEffect(xi.effect.COLURE_ACTIVE, effectParams)\n\n    mob:addGambit(ai.t.SELF, { { ai.c.TIMER, 5 }, { ai.c.RANDOM, 45 } }, { ai.r.ANIM_STRING, ai.s.RANDOM_ANIMATION, 3 })\n\n    mob:setAutoAttackEnabled(false)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/lehko_habhoka.lua"]={["Path"]="scripts/actions/spells/trust/lehko_habhoka.lua",["SHA256"]="38e3dd77a4ad72b632f5b8132f96f88b0fba7ce79175667136fb4cbbecfc7e8e",["Text"]="-----------------------------------\n-- Trust: Lehko Habhoka\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.ROMAA_MIHGO] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.ROBEL_AKBEL] = xi.trust.messageOffset.TEAMWORK_2,\n    })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.MB_AVAILABLE, 0 }, { ai.r.MA, ai.s.MB_ELEMENT, xi.magic.spellFamily.NONE })\n\n    mob:addGambit(ai.t.TARGET, { ai.c.NOT_SC_AVAILABLE, 0 }, { ai.r.MA, ai.s.BEST_AGAINST_TARGET, 0 }, 60)\n\n    ---- Uses Ranged Attacks very frequently. Always runs to stay in melee range. [Verification Needed]\n    ---- Try and ranged attack every 10s\n    mob:addGambit(ai.t.TARGET, { ai.c.ALWAYS, 0 }, { ai.r.RATTACK, 0, 0 }, 10)\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\n\n    mob:addListener('WEAPONSKILL_USE', 'LEHKO_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3231 then -- Debonair Rush\n            --  Here's betting your bark is worrrse than your bite!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    -- MPP 150 migrated to mob_pool_mods\n    -- https://forum.square-enix.com/ffxi/threads/49425-Dec-10-2015-%28JST%29-Version-Update?p=567979&viewfull=1#post567979\n    -- The attribute \"Enhanced Magic Accuracy\" has been added.\n    local power = mob:getMainLvl() / 10\n    mob:addMod(xi.mod.MACC, power)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/leonoyne.lua"]={["Path"]="scripts/actions/spells/trust/leonoyne.lua",["SHA256"]="c21dce1e6fc0a0785e6336c3af708e99522ff3aba64f427ca383ea4bc2eb5e5d",["Text"]="-----------------------------------\n-- Trust: Leonoyne\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/lhe_lhangavo.lua"]={["Path"]="scripts/actions/spells/trust/lhe_lhangavo.lua",["SHA256"]="6a68bcf399f16e6c95ae3695c74219e5cb230dd605b86b61ae1866b58eee6381",["Text"]="-----------------------------------\n-- Trust: Lhe Lhangavo\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/lhu_mhakaracca.lua"]={["Path"]="scripts/actions/spells/trust/lhu_mhakaracca.lua",["SHA256"]="c355ae33c16ba6c816331a5158bb10050538b8fa69aca1a008fa6b1433de0203",["Text"]="-----------------------------------\n-- Trust: Lhu Mhakaracca\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/lilisette.lua"]={["Path"]="scripts/actions/spells/trust/lilisette.lua",["SHA256"]="981e30c276e3a21aeebbbce899b27d44e9e3dd706dbd95a8b7feba34de5f50bf",["Text"]="-----------------------------------\n-- Trust: Lilisette\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.LILISETTE_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/lilisette_ii.lua"]={["Path"]="scripts/actions/spells/trust/lilisette_ii.lua",["SHA256"]="2ff18927fc4f5707b1a00dc7c4b8072b2a0781618fd34308912e04e0083b0500",["Text"]="-----------------------------------\n-- Trust: Lilisette II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.LILISETTE)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/lion.lua"]={["Path"]="scripts/actions/spells/trust/lion.lua",["SHA256"]="e27120998bf7bc18ae373ec5214edd98b18ccf77b25bf29e4de3f7e5c06bda00",["Text"]="-----------------------------------\n-- Trust: Lion\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.LION_II)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    -- TODO: Trust Synergy (Aldo/Lion/Zeid)\n    -- https://www.bg-wiki.com/ffxi/Cipher:_Lion\n\n    local kGrapeshot = 3198\n\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.ZEID] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.ALDO] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.GILGAMESH] = xi.trust.messageOffset.TEAMWORK_3,\n    })\n\n    -- Stun all the things!\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_WS, 0 }, { ai.r.WS, ai.s.SPECIFIC, kGrapeshot })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_MS, 0 }, { ai.r.WS, ai.s.SPECIFIC, kGrapeshot })\n    mob:addGambit(ai.t.TARGET, { ai.c.READYING_JA, 0 }, { ai.r.WS, ai.s.SPECIFIC, kGrapeshot })\n    mob:addGambit(ai.t.TARGET, { ai.c.CASTING_MA,  0 }, { ai.r.WS, ai.s.SPECIFIC, kGrapeshot })\n\n    mob:setTrustTPSkillSettings(ai.tp.ASAP, ai.s.RANDOM)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/lion_ii.lua"]={["Path"]="scripts/actions/spells/trust/lion_ii.lua",["SHA256"]="3b16363615c2e36767487459951186a16e368b61775d014d416a8fb63c1ef92b",["Text"]="-----------------------------------\n-- Trust: Lion II\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.LION)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.teamworkMessage(mob, {\n        [xi.magic.spell.ZEID] = xi.trust.messageOffset.TEAMWORK_1,\n        [xi.magic.spell.PRISHE_II] = xi.trust.messageOffset.TEAMWORK_2,\n        [xi.magic.spell.LILISETTE_II] = xi.trust.messageOffset.TEAMWORK_4,\n        [xi.magic.spell.ARCIELA_II] = xi.trust.messageOffset.TEAMWORK_5,\n    })\n\n    mob:addListener('WEAPONSKILL_USE', 'LION_II_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3493 then -- Powder Keg\n            --  I won't sit by and let Vana'diel be engulged!\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\n\n    mob:addGambit(ai.t.SELF, { ai.c.NOT_STATUS, xi.effect.COPY_IMAGE }, { ai.r.MA, ai.s.HIGHEST, xi.magic.spellFamily.UTSUSEMI })\n\n    mob:setTrustTPSkillSettings(ai.tp.CLOSER_UNTIL_TP, ai.s.RANDOM, 3000)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/luzaf.lua"]={["Path"]="scripts/actions/spells/trust/luzaf.lua",["SHA256"]="c9af995e651dd4eb8156c40bbc0ff6ebb0115125a0698a160a430cc727151d4c",["Text"]="-----------------------------------\n-- Trust: Luzaf\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"},["scripts/actions/spells/trust/maat.lua"]={["Path"]="scripts/actions/spells/trust/maat.lua",["SHA256"]="99937aee2244e8492cf33f73bbe78f228b0f8f69e7ab74fd4717b13b2e2f501d",["Text"]="-----------------------------------\n-- Trust: Maat\n-----------------------------------\n---@type TSpellTrust\nlocal spellObject = {}\n\nspellObject.onMagicCastingCheck = function(caster, target, spell)\n    return xi.trust.canCast(caster, spell, xi.magic.spell.MAAT_UC)\nend\n\nspellObject.onSpellCast = function(caster, target, spell)\n    return xi.trust.spawn(caster, spell)\nend\n\nspellObject.onMobSpawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.SPAWN)\n\n    -- On cooldown\n    mob:addGambit(ai.t.SELF, { ai.c.ALWAYS, 0 }, { ai.r.JA, ai.s.SPECIFIC, xi.ja.MANTRA })\n\n    mob:addListener('WEAPONSKILL_USE', 'MAAT_WEAPONSKILL_USE', function(mobArg, target, skill, tp, action, damage)\n        if skill:getID() == 3263 then -- Bear Killer\n            --  Heh heh heh\n            xi.trust.message(mobArg, xi.trust.messageOffset.SPECIAL_MOVE_1)\n        end\n    end)\nend\n\nspellObject.onMobDespawn = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DESPAWN)\nend\n\nspellObject.onMobDeath = function(mob)\n    xi.trust.message(mob, xi.trust.messageOffset.DEATH)\nend\n\nreturn spellObject\n"}};
